fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants to consider
    let count = std::cmp::min(n as usize, participations.len());
    
    // Count eligible participants
    let eligible = participations
        .iter()
        .take(count)
        .filter(|&&attendance| 5 - attendance >= k)
        .count();
    
    // Return the number of complete teams of 3
    (eligible / 3) as u8
}